#include <bits/stdc++.h>
using namespace std;

vector<double> fftTransform(vector<double> &a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j >= bit; bit >>= 1) {
            j -= bit;
        }
        j += bit;
        if (i < j) {
            swap(a[i], a[j]);
        }
    }
    for (int len = 2; len <= n; len <<= 1) {
        double angle = 2 * M_PI / len * (invert ? -1 : 1);
        double wlenCos = cos(angle);
        double wlenSin = sin(angle);
        for (int i = 0; i < n; i += len) {
            double wCos = 1;
            double wSin = 0;
            for (int j = 0; j < len / 2; j++) {
                int u = i + j;
                int v = i + j + len / 2;
                double uVal = a[u];
                double vVal = a[v] * wCos + a[v] * wSin;
                a[u] = uVal + vVal;
                a[v] = uVal - vVal;
                double tempW = wCos;
                wCos = wCos * cos(angle) - wSin * sin(angle);
                wSin = wSin * cos(angle) + tempW * sin(angle);
            }
        }
    }
    if (invert) {
        for (int i = 0; i < n; i++) {
            a[i] /= n;
        }
    }
    return a;
}

vector<int> polyMultiply(const vector<int> &a, const vector<int> &b, int mod) {
    int size = 1;
    while (size < (int)a.size() + (int)b.size() - 1) size <<= 1;
    vector<double> A(size, 0), B(size, 0);
    for (size_t i = 0; i < a.size(); i++) A[i] = a[i];
    for (size_t i = 0; i < b.size(); i++) B[i] = b[i];
    fftTransform(A, false);
    fftTransform(B, false);
    for (int i = 0; i < size; i++) {
        A[i] *= B[i];
    }
    fftTransform(A, true);
    vector<int> result(a.size() + b.size() - 1);
    for (size_t i = 0; i < result.size(); i++) {
        result[i] = (int)round(A[i]) % mod;
    }
    return result;
}

